def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track seen classes and a list for the minimal bases
        seen = set()
        minimal = []

        # Iterate over the classes in reverse order to maintain MRO
        for cls in reversed(classes):
            # If the class is not already seen, add it to the minimal list
            if cls not in seen:
                minimal.append(cls)
                # Update seen with all superclasses of the current class
                seen.update(cls.__mro__)

        # Return the minimal list in the original order
        return list(reversed(minimal))
    except AttributeError:
        # Handle the case where the input is not a list of classes
        raise ValueError("Input must be a list of class types")

