def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != 2:
        raise ValueError("field_names must contain exactly two elements")

    graph_points = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left_edge
        elif get_coordinate == "right":
            x = bin_.right_edge
        elif get_coordinate == "middle":
            x = (bin_.left_edge + bin_.right_edge) / 2

        y = make_value(bin_.content)

        if not isinstance(y, (int, float)) and not (isinstance(y, tuple) and all(isinstance(v, (int, float)) for v in y)):
            raise ValueError("make_value must return a numeric value or a tuple of numeric values")

        graph_points.append((x, y))

    graph_scale = hist.scale if scale is True else scale

    return {
        "points": graph_points,
        "scale": graph_scale,
        "fields": field_names
    }

