def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import Invalid, providedBy
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(method for name, method in iface.namesAndDescriptions() if inspect.isfunction(method))
    required_attributes = set(name for name, method in iface.namesAndDescriptions() if not inspect.isfunction(method))

    candidate_methods = set(name for name, method in inspect.getmembers(candidate, predicate=inspect.ismethod))
    candidate_attributes = set(name for name, attr in inspect.getmembers(candidate, predicate=lambda a: not inspect.ismethod(a)))

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        errors.extend(f"Missing method: {method}" for method in missing_methods)

    missing_attributes = required_attributes - candidate_attributes
    if missing_attributes:
        errors.extend(f"Missing attribute: {attr}" for attr in missing_attributes)

    for method_name in required_methods:
        if method_name in candidate_methods:
            required_signature = inspect.signature(iface[method_name])
            candidate_signature = inspect.signature(getattr(candidate, method_name))
            if required_signature != candidate_signature:
