def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("At least one base class must be provided")

    metaclasses = set()
    for base in bases:
        metaclass = type(base)
        if metaclass not in metaclasses:
            metaclasses.add(metaclass)

    if explicit_mc is not None:
        metaclasses.add(explicit_mc)

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common metaclass
    common_metaclass = None
    for metaclass in metaclasses:
        if all(issubclass(m, metaclass) for m in metaclasses):
            if common_metaclass is None or issubclass(metaclass, common_metaclass):
                common_metaclass = metaclass

    if common_metaclass is not None:
        return common_metaclass

    raise TypeError("Metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

